namespace Turian.Tests;

/// <summary>
/// #313 keeps third-party assemblies out of the repository: a brick's <c>Precast~</c> payload is build output, and
/// its NuGet copies are generated by <c>brick sync-precast</c> or embedded by <c>brick pack</c>. These guard the
/// ignore rule, so neither a synced copy nor a built assembly can slip in.
/// </summary>
public sealed class PrecastIgnoreTests
{
    /// <summary>No file under any <c>Precast~</c> folder is tracked.</summary>
    [Fact]
    public void NoPrecastPayloadIsTracked()
    {
        var tracked = Git("ls-files", "*Precast~*");

        Assert.True(tracked.ExitCode == 0, tracked.Output);
        Assert.Empty(tracked.Output.Split('\n', StringSplitOptions.RemoveEmptyEntries));
    }

    /// <summary>The render brick's synced third-party copy stays ignored, which is the invariant this guards.</summary>
    [Fact]
    public void SyncedCopiesStayIgnored()
    {
        var probe = Path.Combine(ProjectPackages.BuiltinDirectory, ProjectPackages.RenderBrick, "Precast~", "lib",
            "Silk.NET.Vulkan.dll");

        var check = Git("check-ignore", "-q", probe);

        Assert.True(check.ExitCode == 0,
            $"{probe} is no longer ignored, so Precast~ payloads would start being committed.");
    }

    static string Repository => Path.GetFullPath(Path.Combine(ProjectPackages.BuiltinDirectory, "..", ".."));

    static (int ExitCode, string Output) Git(params string[] arguments)
    {
        var start = new ProcessStartInfo("git")
        {
            WorkingDirectory = Repository,
            RedirectStandardOutput = true,
            RedirectStandardError = true
        };
        foreach (var argument in arguments)
        {
            start.ArgumentList.Add(argument);
        }

        using var process = Process.Start(start)!;
        var output = process.StandardOutput.ReadToEnd();
        var error = process.StandardError.ReadToEnd();
        process.WaitForExit();
        return (process.ExitCode, output + error);
    }
}
